class Solution {
public:
    int countStableSubsequences(vector<int>& nums) {
        const long long MOD=1000000007;
        long long dp[2][3]={};
        for(int x:nums) {
            int p=x&1,q=p^1;
            long long one=(1+dp[q][1]+dp[q][2])%MOD;
            long long two=dp[p][1];
            dp[p][1]=(dp[p][1]+one)%MOD;
            dp[p][2]=(dp[p][2]+two)%MOD;
        }
        return (dp[0][1]+dp[0][2]+dp[1][1]+dp[1][2])%MOD;
    }
};
